class NumRefills {
  public int solve(int a, int b) {
    // "Can we pour 'numPours' times?"
    int k = 1;
    while (k * 2 * b <= a) {
      k *= 2;
    }

    int l = k;
    int r = k * 2;
    while (r - l > 1) {
      int gap = r - l;
      int halfGap = gap >> 1; // Bit shift instead of division
      int mid = l + halfGap;
      if (mid * b <= a) {
        l = mid;
      } else {
        r = mid;
      }
    }
    return l;
  }
}

